export interface ReviewReuseDiscriminationInput {
  prior: ReviewVerdict;
  diff: string;
  report: string;
  headCheckoutDir: string;
  baseCheckoutDir: string;
  baseUnreadablePaths?: ReadonlySet<string>;
  baseIsCheckout?: boolean;
  addedTestFiles?: ReadonlySet<string>;
  taskDeclaredFiles?: string[];
  execProof?: ProofExecutor;
}

export type ReviewReuseDiscriminationResult =
  | { ok: true; verdict: ReviewVerdict }
  | { ok: false; reason: string };

export function discriminateReviewReuse(
  input: ReviewReuseDiscriminationInput,
): ReviewReuseDiscriminationResult {
  const prepared = prepareReviewReuse(input);
  if (!prepared.ok) return prepared;
  const computed = judgeReview(prepared.criteria, reviewReuseEvidence(input));
  return assessReviewReuse(input, prepared.criteria, computed);
}

export async function discriminateReviewReuseAsync(
  input: ReviewReuseDiscriminationInput,
): Promise<ReviewReuseDiscriminationResult> {
  const prepared = prepareReviewReuse(input);
  if (!prepared.ok) return prepared;
  const computed = await judgeReviewAsync(prepared.criteria, reviewReuseEvidence(input));
  return assessReviewReuse(input, prepared.criteria, computed);
}

function prepareReviewReuse(input: ReviewReuseDiscriminationInput):
  | { ok: true; criteria: AcceptanceCriterion[] }
  | { ok: false; reason: string } {
  const criteria: AcceptanceCriterion[] = input.prior.criteria.map((criterion) => ({
    claim: criterion.claim,
    proof: criterion.proof,
  }));
  if (criteria.length === 0) return { ok: false, reason: "prior verdict has no criteria" };
  if (criteria.some((criterion) => !criterion.claim.trim() || !criterion.proof.trim())) {
    return { ok: false, reason: "prior verdict has an unreadable criterion or proof" };
  }
  if (!input.headCheckoutDir || !input.baseCheckoutDir) {
    return { ok: false, reason: "PR-head or merge-base checkout is unavailable" };
  }
  return { ok: true, criteria };
}

function reviewReuseEvidence(input: ReviewReuseDiscriminationInput): ReviewEvidence {
  return {
    diff: input.diff,
    report: input.report,
    semantic: input.prior.criteria.map((criterion) => (criterion.met ? undefined : false)),
    headCheckoutDir: input.headCheckoutDir,
    baseCheckoutDir: input.baseCheckoutDir,
    baseUnreadablePaths: input.baseUnreadablePaths,
    baseIsCheckout: input.baseIsCheckout,
    addedTestFiles: input.addedTestFiles,
    execProof: input.execProof,
    taskDeclaredFiles: input.taskDeclaredFiles,
  };
}

/** W1-T7837 — THE ONE DEFINITION OF "THIS PROOF NEVER RAN BECAUSE OF THE HOST". A criterion whose
 *  proof was skipped for a missing runner, a vanished checkout, an incomplete or broken runtime, or no
 *  execution context — or whose execution threw or could not read the base — says nothing about the PR
 *  body, so no body edit can change it. {@link assessReviewReuse} (unreadable evidence) and the capped
 *  block's re-review route both read this predicate, so the two cannot drift. */
export function isHostGapCriterion(
  criterion: { readonly proof_exec?: string; readonly proof_skip?: string },
): boolean {
  return (
    criterion.proof_exec === "exec_error" ||
    criterion.proof_exec === "base_unreadable" ||
    criterion.proof_skip === "runner-absent" ||
    criterion.proof_skip === "cwd-missing" ||
    criterion.proof_skip === "incomplete-run" ||
    criterion.proof_skip === "runtime-broken" ||
    criterion.proof_skip === "no-exec-context"
  );
}

/** An attributed host-gap attempt. Missing `completed` preserves the prevalidated helper API. */
export interface HostGapRereview { atMs: number; skips: readonly string[]; attemptId?: string; completed?: boolean }
export interface HostGapAttribution {
  state: "complete" | "incomplete";
  currentInputKnown: boolean;
  unattributedRequests: number;
  incompleteAttempts: number;
  unboundAdmissions: number;
  unboundTerminals: number;
}
const completedHostGapCount = (history: readonly HostGapRereview[]): number => history.filter(r => r.completed !== false).length;

/** The host problem behind a grade — the sentence an escalation carries. */
export function hostGapProblem(skip: string): string {
  switch (skip) {
    case "runner-absent": return "sandbox runner missing";
    case "cwd-missing": return "review worktree reclaimed";
    case "runtime-broken": return "runtime broken";
    case "incomplete-run": return "runtime broken (run ended without its summary)";
    case "no-exec-context": return "no PR-head checkout to execute in";
    case "exec_error":
    case "exec-error": return "proof execution threw";
    case "base_unreadable": return "merge-base checkout unreadable";
    default: return skip;
  }
}

/** Wait before the next host-gap re-review: one observed review duration, grown by each prior re-review. */
export function hostGapRereviewWaitMs(observedReviewMs: number, priorRereviews: number): number {
  return Math.max(0, observedReviewMs) * (priorRereviews + 1);
}

export interface HostGapRereviewState {
  history: readonly HostGapRereview[];
  attribution?: HostGapAttribution;
  skips: readonly string[];
  lastReviewAtMs?: number;
  observedReviewMs: number;
  nowMs: number;
}

export type HostGapRereviewAction =
  | { kind: "rereview"; reason: string; progress?: FixProgressResult }
  | { kind: "hold"; reason: string; progress?: FixProgressResult }
  | { kind: "escalate"; reason: string; progress?: FixProgressResult };

const sortedUnique = (values: readonly string[]) => [...new Set(values)].sort();

/** Fix-progress judge input for a persisting host gap: each re-review is a no-op round on the branch. */
export function hostGapProgressInput(
  base: { taskId?: string; prNumber?: number; headSha: string },
  state: Pick<HostGapRereviewState, "history" | "skips">,
): FixProgressInput {
  const currentRed = sortedUnique(state.skips.map((skip) => `host-gap:${skip}`));
  const rounds = state.history.map((entry, index) => ({
    id: entry.attemptId ?? `host-gap:${index}`, dispatchedHead: base.headSha, pushedHead: base.headSha,
    redBefore: sortedUnique(entry.skips.map((skip) => `host-gap:${skip}`)), completed: entry.completed !== false,
  }));
  rounds.forEach((round, index) => Object.assign(round, { redAfter: rounds[index + 1]?.redBefore ?? currentRed }));
  const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);
  const completed = rounds.filter(r => r.completed);
  return { taskId: base.taskId, prNumber: base.prNumber, headSha: base.headSha, strikesSpent: completed.length, currentRed,
    rounds: rounds as FixProgressInput["rounds"], formerCeiling: 1,
    parkedReason: `host-gap-rereview: ${completed.length} completed re-reviews, ${rounds.length - completed.length} incomplete`,
    signals: { noOpRounds: completed.length,
      identicalRedSets: completed.filter((round) => same(round.redBefore, (round as { redAfter?: string[] }).redAfter)).length,
      identicalDiffs: 0, oscillating: false, refusedRounds: 0, incompleteRounds: rounds.length - completed.length, reviewerOnlyFailurePersists: 0 } };
}

/** W1-T7837 — next step for a capped verdict whose every proof hit a host gap: never a body or shard
 *  repair, but a paced re-review of the same head, or an escalation once the fix-progress judge says so. */
export async function planHostGapRereview(
  state: HostGapRereviewState,
  opts: FixProgressWitness & { judge?: FixProgressJudge; input: FixProgressInput; ledger?: readonly Record<string, unknown>[];
    log?: (step: string, fields: Record<string, unknown>) => void },
): Promise<HostGapRereviewAction> {
  const prior = completedHostGapCount(state.history);
  const problems = sortedUnique(state.skips.map(hostGapProblem)).join(", ");
  const anchor = Math.max(state.lastReviewAtMs ?? Number.NEGATIVE_INFINITY,
    ...state.history.filter(entry => entry.completed !== false).map((entry) => entry.atMs));
  const waitMs = hostGapRereviewWaitMs(state.observedReviewMs, prior);
  if (Number.isFinite(anchor) && state.nowMs < anchor + waitMs) {
    return { kind: "hold", reason: `capped review could not run its proofs (${problems}) — a host gap, not a body defect; ` +
      `re-review ${prior + 1} is paced ${Math.ceil((anchor + waitMs - state.nowMs) / 60_000)}m out ` +
      `(${Math.ceil(waitMs / 60_000)}m derived from ${prior} prior host-gap re-review(s) and the observed review duration)` };
  }
  if (prior >= 1) {
    const { decision: progress, receipt } = await resolveFixProgress(opts.input, opts.ledger ?? [], opts);
    opts.log?.(receipt.step, { ...receipt, site: "host-gap-rereview", pr_number: opts.input.prNumber,
      head_sha: opts.input.headSha, parked_reason: opts.input.parkedReason, round_count: opts.input.rounds.length,
      signals: opts.input.signals, ...failureEvidenceField(opts.input), ...progress });
    if (progress.verdict === "unavailable") return { kind: "hold", reason: progress.reason, progress };
    if (progress.verdict === "escalate") {
      return { kind: "escalate", progress, reason: `host gap persists across ${prior} re-review(s) — ` +
        `${state.skips.join(", ")} (${problems}); fix progress loop: ${progress.loop} — ${progress.reason}` };
    }
    return { kind: "rereview", progress, reason: `host-gap re-review ${prior + 1}: ${progress.reason}` };
  }
  return { kind: "rereview", reason: `capped review could not run its proofs (${problems}) — a host gap a PR-body edit cannot fix; ` +
    `re-reviewing the same head and body` };
}

function assessReviewReuse(
  input: ReviewReuseDiscriminationInput,
  criteria: AcceptanceCriterion[],
  computed: ReviewVerdict,
): ReviewReuseDiscriminationResult {
  // W1-T4423: a plan-only verdict rests on a lint-plan run this reuse path does not repeat.
  if (computed.planOnly) return { ok: false, reason: "a plan-only verdict needs a full review to re-run lint-plan" };

  const unreadable = computed.criteria.find(isHostGapCriterion);
  if (unreadable) {
    return {
      ok: false,
      reason: `proof evidence unreadable for ${unreadable.claim}: ${unreadable.proof_skip ?? unreadable.proof_exec}`,
    };
  }

  for (const criterion of criteria) {
    const whitelisted = parseWhitelistedProof(criterion.proof);
    if (whitelisted?.kind === "test" && input.baseIsCheckout !== true) {
      return { ok: false, reason: `unit-test base discrimination is unavailable for ${criterion.claim}` };
    }
  }

  const notObserved = computed.criteria.find(
    (criterion) => criterion.proof_exec !== "executed_pass" && criterion.proof_exec !== "executed_fail" && criterion.proof_exec !== "executed_stale",
  );
  if (notObserved) {
    return { ok: false, reason: `proof discrimination did not produce an observed result for ${notObserved.claim}` };
  }

  const criteriaWithPriorFailures = computed.criteria.map((criterion, index) => {
    const prior = input.prior.criteria[index];
    if (!prior || prior.met) return criterion;
    return {
      ...criterion,
      met: false,
      reason: `${criterion.reason} — prior criterion failure preserved during proof-only discrimination`,
    };
  });
  const preservedFailure = input.prior.state === "failure";
  return {
    ok: true,
    verdict: {
      ...computed,
      criteria: criteriaWithPriorFailures,
      state: preservedFailure || criteriaWithPriorFailures.some((criterion) => !criterion.met) ? "failure" : computed.state,
      floorState: preservedFailure ? "failure" : computed.floorState,
      summary: preservedFailure ? input.prior.summary : computed.summary,
    },
  };
}

/**
 * The escalation's TASK IDENTITY for one open PR — pure, so the mint itself is testable without
 * reaching the `escalate` closure's real issue gateway.
 *
 * A PR carrying a `Remudero-Task:` trailer escalates under its own task id. A PR without one is the
 * OPERATOR-LANE agent PR — the class with neither a task nor a run id — and it used to be stamped
 * the literal string `"UNKNOWN"`. That is not a plan task id, so
 * `buildEscalationReconcileCandidates`'s `plan.byId.get(taskId)` missed it and the resulting issue
 * could NEVER be retired: 53 of 57 open needs-human issues carried `**Task:** UNKNOWN` while the
 * reconciler's population read 0 on every pass.
 *
 * `PR-<n>` is NOT a new convention — it is the SAME synthetic id the review lane already mints at
 * four call sites in this file, so an operator grepping either surface sees ONE identity for the
 * PR. And it round-trips: {@link buildEscalationReconcileCandidates} resolves a `PR-<n>` referent
 * directly from the number, because an id that is enumerable but UNDERIVABLE would convert a
 * visible orphan into an invisible one, which is strictly worse than leaving it alone.
 */
/** The stalled-stage reason as an escalation SUMMARY: its age and episode start dropped. A stalled-stage
 *  escalation dedups on its exact title (`headDedup: "independent"`), and the title carried "for 32 minutes" and
 *  "since <ts>", so each pass that re-escalated the same (PR, blocker, diagnosis) after a restart or a re-read
 *  episode opened a NEW issue: #11698 and #11720 for #11679, same head and contract, 85 minutes apart. The full
 *  reason, with its age and start, stays in the issue's detail. Any other reason is returned unchanged. */
export function stalledStageEscalationSummary(reason: string): string {
  return reason.replace(/^(PR stage stalled: .+?) for \d+ minutes \(BACKSTOP \d+\); since [^;]*;/, "$1;");
}

export function escalationTaskIdFor(pr: { taskId?: string; prNumber: number }): string {
  // W1-T5866: the `unfiled` branch-shape sentinel is every ad-hoc PR's id, never one PR's — it maps to `PR-<n>` here
  // exactly as it does for the review rows (W1-T5839), so two run-unfiled PRs never share an escalation.
  return reviewLedgerKeyFor(pr.taskId, pr.prNumber);
}

/** W1-T5866 — THE KEY THIS PR's FIX-LANE ROWS ARE READ UNDER: {@link escalationTaskIdFor}'s identity, but
 *  `undefined` stays `undefined` (a PR with no id at all has no strike history to read, as before). A run-unfiled PR
 *  is `PR-<n>`, so its strikes, refusals and fix claims are its own instead of one `unfiled` budget every ad-hoc PR
 *  shares. Legacy `unfiled`-keyed rows carry no `pr_url`, so they are not reattributed to any one PR. */
export function fixLedgerTaskIdFor(pr: { taskId?: string; prNumber: number }): string | undefined {
  return pr.taskId === undefined ? undefined : reviewLedgerKeyFor(pr.taskId, pr.prNumber);
}

/** W1-T5866 — the id the fix lane's branch-OWNERSHIP check uses: a run-unfiled PR's own `run-unfiled-<epochMs>` head is
 *  still owned by the `unfiled` shape even though its rows are keyed `PR-<n>`. Any other PR keeps the task's own id. */
export function fixOwnershipIdFor(prTaskId: string | undefined, taskId: string): string {
  return prTaskId === UNFILED_RUN_SENTINEL ? UNFILED_RUN_SENTINEL : taskId;
}

/** W1-T5866 — the `task_id` a review-outcome / `sweep.review_admitted` row dedups under. A run-unfiled PR is `PR-<n>`
 *  whether or not this pass classified it a plan filing; a digest-less legacy caller keeps the empty fallback. */
export function reviewOutcomeTaskIdFor(pr: { taskId?: string; prNumber: number; reviewInputDigest?: string }): string {
  return pr.reviewInputDigest !== undefined ? reviewLedgerKeyFor(pr.taskId, pr.prNumber) : (pr.taskId ?? "");
}

/**
 * W1-T516 — the SWEEP's OWN task-id resolution for one PR's arm attempt, gated on the
 * `sweep.armSessionPrs` policy flag.
 *
 * THE DEFECT THIS CLOSES. `buildSweepEffects`'s `arm` dep used to pass `pr.taskId` RAW to
 * {@link armAndLogOutcome}, while the review lane (`task_id: taskId ?? PR-<n>`), the
 * escalation lane ({@link escalationTaskIdFor}), and `approveCommand` all mint the SAME
 * `PR-<n>` synthetic id for exactly this case — a PR with no `Remudero-Task:` trailer. The
 * sweep was the ONE caller that did not, so `armAutoMerge`'s `if (!taskId)` branch refused
 * every session PR the sweep reviewed, unconditionally.
 *
 * OFF (the default): returns `pr.taskId` unchanged — a session PR still resolves to
 * `undefined` and `armAutoMerge` still refuses at `no-task-id`, byte-for-byte the pre-
 * existing behaviour.
 *
 * ON: mints the SAME `PR-<n>` fallback {@link escalationTaskIdFor} already mints, so the id
 * this arm passes is the exact key `decideArmFromLedgerVerdict` already finds the review
 * lane's own verdict under — no new ledger shape, no second synthetic id.
 */
export function sweepArmTaskId(pr: { taskId?: string; prNumber: number }, armSessionPrs: boolean): string | undefined {
  // W1-T5866: deliberately NOT {@link escalationTaskIdFor} — the arm gate reads rows already scoped to this PR's url
  // (armLedgerLinesForPr), and a legacy `unfiled`-keyed row must keep matching the id the arm passes.
  return armSessionPrs ? (pr.taskId ?? `PR-${pr.prNumber}`) : pr.taskId;
}

/** W1-T5813 — the arm's ledger gate reads only THIS PR's `review.posted` rows (a legacy row with
 *  no `pr_url` stays). `unfiled` is the sentinel every run-unfiled PR shares, so the gate's last-row-wins
 *  read handed #9155 another PR's verdict: `ledger-refused` at 03:37, 04:02, 04:10 and 04:20Z. */
export function armLedgerLinesForPr(
  lines: Array<Record<string, unknown>>,
  prUrl: string,
): Array<Record<string, unknown>> {
  return lines.filter((line) => line.step !== "review.posted" || typeof line.pr_url !== "string" || line.pr_url === prUrl);
}

/**
 * THE TASK THE FIX RUNG REPAIRS AGAINST — the plan task when the PR has one, otherwise a SYNTHETIC
 * stand-in keyed by the SAME id the review lane and the escalation lane already mint.
 *
 * THE DEFECT (impl-FY). `dispatchFix` looked the PR's task up in the plan and returned when it
 * found none, logging `sweep.fix.no_task`. An agent-authored PR has a descriptive branch and no
 * `Remudero-Task:` trailer, so it matches no task — and the rung that exists to repair a CI-failing
 * PR could not act on it. Measured: #1115, #1116, #1117, #1118, #1120, #1127 and #1132 all logged
 * `sweep.fix.no_task` with `task_id=(none)`, #1132 while dispositioned `blocked-fixable` — the
 * sweep correctly identifying a fixable PR and then doing nothing, every poll, silently.
 *
 * NOT A SECOND MECHANISM: the id comes from {@link escalationTaskIdFor} — `pr.taskId ?? PR-<n>`,
 * the SAME synthetic form `reviewCommand` writes its `review.posted` key with, so one PR has ONE
 * identity across the review, escalation and fix surfaces.
 *
 * AND IT IS WHAT MAKES THE CAP BIND. `priorStrikesFor` returns 0 for an undefined taskId, so an
 * un-synthesised PR would have been not merely reachable but UNBOUNDED — the same shape as the
 * defect. With the id present the strike cap keys on it exactly as it does for a plan task.
 *
 * `risk` is DEFAULT_RISK because a mount must resolve and a PR carries no risk field.
 */

/**
 * `acceptance` FOR A SYNTHETIC TASK (round 2, PR #1146's own review-floor failure): the ORIGINAL
 * premise here — "empty because a no-task PR has no plan criteria, which costs nothing since the
 * only disposition reaching this path seeds `criteria: []` and targets FAILING CHECKS, never a
 * review verdict" — is FALSE for a `blocked_review` disposition. That disposition DOES reach this
 * path for a synthetic (no-task) PR, and `runFixRung`'s post-strike `runReview` call judges
 * `task.acceptance` DIRECTLY (`criteria = task.acceptance ?? []`, never re-reading the PR body) —
 * so a hardcoded `[]` here made every synthetic-task review permanently unjudgeable
 * ("no acceptance criteria to judge (fail closed)"), regardless of what the fix worker changed,
 * on EVERY strike after the first: an unfixable loop, not merely a no-op one. `caller`-supplied
 * `body` closes it the SAME way `reviewCommand` already resolves criteria for a manual/plan PR —
 * `parseAcceptanceBlock` over the PR body's `## Acceptance` block — so a synthetic task carries
 * the SAME criteria a human `rmd review` run would find, instead of none.
 *
 * `files` FOR A SYNTHETIC TASK (W1-T4460): the ORIGINAL premise here — a synthetic task carries no
 * `files:`, which costs nothing because `commitWorkerEdits` (run-task.ts) only ever refuses a
 * change OUTSIDE a declared surface — is FALSE. `commitWorkerEdits` refuses OUTRIGHT, before
 * looking at a single changed path, when `declaredPaths.length === 0`: "the task declares no
 * files, so there is no surface to stage". Measured: #6807, #6804, #6803 ($9.55) and #6879 made
 * real, valid edits on a no-task PR and had every one of them discarded this way — 8 of 65
 * measured fix rounds. `changedPaths` is the PR's OWN footprint (its current `gh pr view --json
 * files` list, read once by the caller alongside `body`/`headRefName` so this adds no second
 * network read) — an edit that stays inside the PR's existing diff now has a surface to commit
 * against, exactly the shape `pathIsUnderDeclaredSurface` already grants a plan task.
 */
export function fixRungTaskFor(
  plan: Plan,
  pr: { prNumber: number; taskId?: string },
  body?: string,
  headRefName?: string,
  changedPaths?: readonly string[],
): { task: { id: string; title: string; risk: TaskRisk; acceptance: AcceptanceCriterion[]; budget_usd?: number; files: string[] }; synthetic: boolean } {
  const found = pr.taskId ? plan.tasks.find((t) => t.id === pr.taskId) : undefined;
  if (found) return { task: found as never, synthetic: false };
  const branchTaskId = taskIdFromRunBranch(headRefName);
  const syntheticLaneId = branchTaskId && /^(?:RETRO|TRIAGE-.+|PLAN-.+|APPROVE-.+)$/.test(branchTaskId)
    ? branchTaskId
    : undefined;
  return {
    task: {
      // A plan-only lane PR deliberately has no credited task, even when its body carries a lane
      // trailer. The fix rung still needs the lane identity to recognize that
      // `run-RETRO-*`/TRIAGE/PLAN/APPROVE is its own head. Restrict this fallback to the four
      // orchestrator lane namespaces; a synthetic PR on `run-W1-T*` remains foreign and refused.
      id: (pr.taskId === UNFILED_RUN_SENTINEL ? undefined : pr.taskId) ?? syntheticLaneId ?? escalationTaskIdFor(pr),
      title: `PR #${pr.prNumber}`,
      risk: DEFAULT_RISK,
      acceptance: body ? parseAcceptanceBlock(body) : [],
      files: changedPaths ? [...new Set(changedPaths)].sort() : [],
    },
    synthetic: true,
  };
}

/** The closed set of ids that are never plan tasks: a `PR-<n>` escalation id and the four orchestrator lanes. */
type FixRungTask = {
  id: string;
  title: string;
  risk: TaskRisk;
  acceptance: AcceptanceCriterion[];
  budget_usd?: number;
  files: string[];
};

const NEVER_A_PLAN_TASK_ID = /^(?:PR-\d+|RETRO|TRIAGE-.+|PLAN-.+|APPROVE-.+)$/;

/**
 * W1-T4460 design note (ii): a PR's task id can be genuinely ABSENT from the plan SNAPSHOT this
 * sweep loaded without being absent from the plan itself — the snapshot merely predates the shard
 * that files it (#6916/W1-T4413: the shard landed via #6910 after this poll's `plan` was read), so
 * a real task looked unfiled and `fixRungTaskFor` minted it a synthetic identity forever after,
 * even once the plan caught up on the next poll's OWN read (this call never re-reads).
 *
 * Retried BLIND this would repeat the identical miss for every `PR-<n>`/orchestrator-lane id
 * (`RETRO`/`TRIAGE-*`/`PLAN-*`/`APPROVE-*`), which are never plan tasks and never benefit from a
 * reload — so the reload is attempted only when `pr.taskId` is set, absent from `plan`, AND does
 * not already match one of those synthetic shapes. `reloadPlan` is optional and swallowed on
 * failure (an unreadable plan on this one read is not this dispatch's problem to raise) so a
 * caller that omits it, or whose reload throws, degrades to exactly today's `fixRungTaskFor`
 * behaviour. `daemon.plan_reloaded` is the SAME step literal `runDaemon`'s own top-of-tick reload
 * already logs (design note iv) — one meaning, two writers, not a second mechanism.
 */
export function fixRungTaskWithPlanReload(
  plan: Plan,
  pr: { prNumber: number; taskId?: string },
  body: string | undefined,
  headRefName: string | undefined,
  changedPaths: readonly string[] | undefined,
  reloadPlan: (() => Plan | undefined) | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
): { task: ReturnType<typeof fixRungTaskFor>["task"]; synthetic: boolean } {
  const staleSnapshotMiss =
    pr.taskId !== undefined &&
    !plan.tasks.some((t) => t.id === pr.taskId) &&
    !NEVER_A_PLAN_TASK_ID.test(pr.taskId);
  if (staleSnapshotMiss && reloadPlan) {
    let fresh: Plan | undefined;
    try {
      fresh = reloadPlan();
    } catch {
      // An unreadable plan on this ONE opportunistic re-read is not this dispatch's reason to
      // throw — falling through to the stale `plan` below reproduces exactly today's behaviour.
      fresh = undefined;
    }
    if (fresh) {
      log("daemon.plan_reloaded", { tasks: fresh.tasks.length });
      return fixRungTaskFor(fresh, pr, body, headRefName, changedPaths);
    }
  }
  return fixRungTaskFor(plan, pr, body, headRefName, changedPaths);
}

/**
 * W1-T4073: whether {@link fixRungTaskAtHead} has a plan record to look for — a real plan task id,
 * never the `PR-<n>`/orchestrator-lane shapes (no record exists at any head, so the read is waste).
 */
export function fixRungWantsHeadContract(pr: { taskId?: string }): pr is { taskId: string } {
  return pr.taskId !== undefined && !NEVER_A_PLAN_TASK_ID.test(pr.taskId);
}

/**
 * W1-T4073: the fix rung's task contract AT THE PR HEAD it is repairing, not the daemon's boot
 * snapshot. The #6630 round rendered `task.files` from a plan 27 minutes stale, so the worker built
 * a test file #6627 had already replaced and the harness committed it. `resolved` is
 * `resolvePlanCriteriaAtHead`'s read of `plan/tasks.yaml` at that head (see
 * `resolveFixRungTaskContractAtHead`), and the ONE returned task feeds the prompt, the scope guard
 * and the harness commit alike — all three read `opts.task`, so there is no second contract.
 *
 * UNREADABLE NEVER FALLS BACK: an unresolvable head sha, a thrown resolver or a `divergence` stands
 * the round down, named — the snapshot is the very thing this task refuses to trust. A record the
 * head plan does not carry at all (a readable plan, no such id) is NOT unreadable: it leaves the
 * task exactly as `fixRungTaskWithPlanReload` resolved it. One the head DOES carry replaces
 * acceptance, files, risk and budget and is never synthetic, even when the snapshot lacked it.
 */
export function fixRungTaskAtHead(
  current: { task: FixRungTask; synthetic: boolean },
  taskId: string,
  resolved: PlanCriteriaAtHeadResult | undefined,
  resolveError?: string,
): { standDown: string } | { task: FixRungTask; synthetic: boolean } {
  if (resolved === undefined || resolved.divergence !== undefined) {
    const why = resolveError ?? resolved?.divergence?.reason ?? "no contract returned";
    return { standDown: `fix rung: PR-head task contract unreadable — ${why}` };
  }
  const carried =
    resolved.criteria.length > 0 || resolved.taskDeclaredFiles !== undefined || resolved.taskRisk !== undefined;
  if (!carried) return current;
  const { task } = current;
  return {
    task: {
      ...task,
      id: taskId,
      risk: resolved.taskRisk ?? task.risk,
      acceptance: resolved.criteria,
      files: resolved.taskDeclaredFiles ?? [],
      ...(resolved.taskBudgetUsd !== undefined ? { budget_usd: resolved.taskBudgetUsd } : {}),
    },
    synthetic: false,
  };
}

/**
 * W1-T3585 — replay of #5545/W1-T3558 (2026-09-14): a plan resequence merged (#5537) and added an
 * unmet dependency to a task AFTER a worker had already been admitted and opened its implementation
 * PR. Current dispatch (drain.ts's `isDispatchEligible`) will never rebuild that PR — it refuses the
 * task outright — yet the sweep had no current-plan eligibility predicate for an already-open,
 * task-owned PR, so the draft sat open, unbuildable, and undispatchable until an operator closed it
 * by hand.
 *
 * This is the SAME per-task reason family `isDispatchEligible` applies, reduced to the THREE
 * conditions that make a task's own open PR no longer authoritative: a `blocked` status, an
 * explicit `retirement` ruling (a named subtype of `blocked`), or an unmet dependency the CURRENT
 * plan and a freshly-derived {@link MergedResolver} both agree on — never a title, a branch prefix,
 * or a stale snapshot. Returns `undefined` (no closure authority) for a still-runnable task, exactly
 * mirroring `isDispatchEligible`'s own `unmetDependencies(...).length > 0` gate (never re-derived
 * independently) and its `status === "blocked"` split between "retired" and "blocked".
 *
 * PURE: takes the plan/task/resolver a caller already proved fresh; this function never reads a
 * checkout, never fetches, and never infers eligibility on its own.
 */
export function currentPlanIneligibilityReason(plan: Plan, task: Task, isMerged: MergedResolver): string | undefined {
  if (task.status === "blocked") {
    return task.retirement !== undefined
      ? `retired in the current plan (${task.retirement})`
      : "blocked in the current plan";
  }
  const unmet = unmetDependencies(plan, task, isMerged);
  if (unmet.length > 0) {
    return `unmet dependenc${unmet.length === 1 ? "y" : "ies"} in the current plan: ${unmet.join(", ")}`;
  }
  return undefined;
}

/**
 * W1-T4565 — a CLOSE must not rest on one lagging read. `currentPlanIneligibilityReason`'s resolver
 * is the daemon's per-tick projection, which lagged a real merge by 13-28 minutes (MEASURED: the
 * sweep credited W1-T4567 itself at 20:38:57, then closed #7333 at 20:42 for that "unmet"
 * dependency). An unmet dependency the ledger already credits as merged is met: `creditedInLedger`
 * is asked about exactly the unmet ids, and only when a close is proposed. It can only remove a
 * reason, never add one; a `blocked`/retired task is unaffected.
 */
export function corroboratedIneligibilityReason(
  plan: Plan,
  task: Task,
  isMerged: MergedResolver,
  creditedInLedger: (taskIds: readonly string[]) => ReadonlySet<string>,
): string | undefined {
  return corroboratedIneligibility(plan, task, isMerged, creditedInLedger).reason;
}

/** W1-T4633 — {@link corroboratedIneligibilityReason} plus the still-unmet dependency ids AS DATA,
 *  so {@link projectMergedTaskCandidates} can re-check exactly those ids against the pass's fresh
 *  merge credit without parsing them back out of the prose. `unmetDependencies` is empty for a
 *  runnable task and for a blocked/retired one — only the unmet-dependency reason carries ids. */
export function corroboratedIneligibility(
  plan: Plan,
  task: Task,
  isMerged: MergedResolver,
  creditedInLedger: (taskIds: readonly string[]) => ReadonlySet<string>,
): { reason: string | undefined; unmetDependencies: string[] } {
  const reason = currentPlanIneligibilityReason(plan, task, isMerged);
  if (reason === undefined || task.status === "blocked") return { reason, unmetDependencies: [] };
  const unmet = unmetDependencies(plan, task, isMerged);
  const credited = creditedInLedger(unmet);
  if (credited.size === 0) return { reason, unmetDependencies: unmet };
  const corroborated = (t: Task): boolean => isMerged(t) || credited.has(t.id);
  return {
    reason: currentPlanIneligibilityReason(plan, task, corroborated),
    unmetDependencies: unmetDependencies(plan, task, corroborated),
  };
}

/** W1-T4633 — the phrase ONLY the plan-resequence close row's reason carries. runSweep keys the
 *  `keep_head_branch` field of that close's `sweep.disposed` row on it, and the branch reaper
 *  (run-task.ts's `reapBranchesCommand`) keeps every head that field names: the close is described
 *  as reversible, and deleting the head makes reopening depend on someone's local copy. */
export const PLAN_RESEQUENCE_CLOSE_MARKER = "the plan resequenced after this PR was admitted";

/** The synthetic lane namespaces whose PR branches are created by the orchestrator itself. */
function isSyntheticOrchestratorLaneId(taskId: string): boolean {
  return /^(?:RETRO(?:-.+)?|TRIAGE-.+|PLAN-.+|APPROVE-.+)$/.test(taskId);
}

/**
 * W1-T4465 design (i) — is `head` a branch the FLEET itself authored: a dispatched run's own
 * `run-<taskId>-<epochMs>` for a REAL filed task (`taskIdFromRunBranch`'s capture shaped like
 * {@link TASK_ID_TRAILER_RE}), or one of the orchestrator's own synthetic lanes (RETRO/TRIAGE/
 * PLAN/APPROVE, {@link isSyntheticOrchestratorLaneId})?
 *
 * An operator's own `run-unfiled-*` session — the exact incident this task fixes, "4-7 of those
 * open PRs were run-unfiled-* branches (operator sessions), which the fleet neither authored nor
 * can throttle" — and any other non-fleet head (a human feature branch, dependabot, ...) both
 * read `false`: the queue governor's ownership split (design (i)) counts them but never gates
 * dispatch on them.
 *
 * `head === undefined` reads `true` (fail CLOSED, not open): an unresolvable head is a reading the
 * WIP ceiling could not classify, not a confirmed-foreign one, and the ceiling's own asymmetry
 * (never silently admit on an unreadable observation) means it must keep gating rather than
 * silently stop counting toward the limit.
 */
export function isFleetOwnedRunBranch(head: string | undefined): boolean {
  if (head === undefined) return true;
  const owner = taskIdFromRunBranch(head);
  if (owner === undefined) return false;
  return isSyntheticOrchestratorLaneId(owner) || TASK_ID_TRAILER_RE.test(owner);
}

/**
 * Is `head` an acceptable branch for a fix dispatch to amend?
 *
 * FOR A PLAN TASK, unchanged and still strict: the fix must amend THAT task's own run branch,
 * because creditability is load-bearing (status.ts's `ownsBranch`) and a fix on an uncreditable
 * head loops forever and strands dependents.
 *
 * FOR A SYNTHETIC (no-task) PR the entire rationale is inapplicable — there is no task to credit
 * and no dependent to strand — so its own descriptive head is acceptable. ONE guard remains, and it
 * is the load-bearing half: a head that CLAIMS SOME OTHER TASK (`run-W1-T123-…`) is refused. Such a
 * PR is not task-less, it is MIS-TRAILERED, and amending it would push commits onto another task's
 * run branch under a synthetic identity.
 *
 * This never widens WHICH PRs are fixable — the disposition set is untouched — only whether the
 * rung can act on one the sweep has already classified.
 */

/**
 * Is `head` ANY dispatched run's own branch — `run-<taskId>-<epochMs>`, the shape every
 * worker push takes (`const branch = \`run-${runId}\``)? TASK-AGNOSTIC, unlike status.ts's
 * `ownsBranch`/`isBareRunBranch`, which answer "does this head claim THIS task".
 *
 * It is the only authorship signal the review path holds, and W1-T385 wires it to the one
 * consumer that needs it: `runReview` derives `humanAuthored` (see {@link
 * "./lib/review.js".RubricPrMeta.humanAuthored}) as "a head ref exists AND is not this
 * shape". Absent head ⇒ `false` here, so that consumer fails CLOSED.
 *
 * The regex is unchanged from `fixHeadAcceptable`'s own inline copy, which now calls this
 * so the shape has ONE home rather than two that can drift apart.
 */
export function isDispatchedRunBranch(head: string | undefined): boolean {
  return head !== undefined && /^run-.+-\d+$/.test(head);
}

export function fixHeadAcceptable(head: string | undefined, taskId: string, synthetic: boolean): boolean {
  if (!head) return false;
  const ownRunBranch = new RegExp(`^run-${taskId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}-\\d+$`).test(head);
  if (!synthetic) return ownRunBranch;
  const exactSyntheticLaneBranch = isSyntheticOrchestratorLaneId(taskId) && head === `run-${taskId}`;
  // A synthetic id covers two shapes: an agent PR with NO id at all (descriptive branch), and a
  // LANE PR whose id is real but absent from plan.tasks. A lane can have the ordinary
  // `run-<id>-<dispatch epoch>` head or the exact `run-<id>` head when its id already ends in the
  // lane's own epoch. Preserve that full id as the strike/review key; only the ownership
  // equivalence changes. A run branch claiming a DIFFERENT task remains refused.
  return ownRunBranch || exactSyntheticLaneBranch || !isDispatchedRunBranch(head);
}

/**
 * WHY a fix dispatch just declined an uncreditable head, as ONE aggregatable token.
 *
 * `sweep.fix.uncreditable_head` recorded `head`/`synthetic` and no reason at all, so telemetry
 * could not tell whether a run of declines was ONE cause or several: reading `head` alone cannot
 * distinguish a well-formed run branch that claims the WRONG task (`run-W1-T172-<epochMs>`,
 * refused for a different id — two of the seven rows this host's ledger has ever recorded) from
 * one that is not a run branch at all, because the row does not carry the task id being fixed.
 * Both read as "an odd branch name" and neither is actionable.
 *
 * DELIBERATELY A SECOND, INDEPENDENT DERIVATION rather than a value threaded out of
 * {@link fixHeadAcceptable}: it consults that predicate as an ORACLE first and reports
 * `"unclassified"` — never a guess — whenever the predicate says the head IS acceptable and this
 * classifier therefore has no refusal to explain. That is the catch-all's whole purpose: it is
 * reachable ONLY when the two disagree, so a future change to `fixHeadAcceptable` that this
 * function is not taught about surfaces in telemetry as an honest "unattributed" rather than as a
 * confidently wrong cause. It is named to read that way on a dashboard.
 */

/**
 * The reasons, exhaustive over today's predicate:
 *   - `head_unresolved`    — `gh pr view` resolved no `headRefName`. The SAME `!head` case the
 *                            predicate's own first guard refuses, and the one the call site's
 *                            `!realBranch` arm reaches without ever calling the predicate.
 *   - `foreign_run_branch` — the head IS `run-<id>-<epochMs>` ({@link isDispatchedRunBranch}) but
 *                            not THIS task's own. Reachable under BOTH `synthetic` values, and the
 *                            only one reachable when `synthetic` is true: a synthetic PR whose head
 *                            claims some other task is MIS-TRAILERED, not task-less.
 *   - `not_a_run_branch`   — the head is not run-shaped at all (`fix/…`, `feat/…`). Reachable ONLY
 *                            when `synthetic` is false, because the predicate ACCEPTS exactly this
 *                            shape for a synthetic PR — so a `not_a_run_branch` row carrying
 *                            `synthetic: true` is by construction impossible and would itself be a
 *                            signal worth reading.
 *   - `unclassified`       — see above. Never a real cause.
 *
 * Pure, synchronous, no clock and no I/O — unit-testable against the same fixtures
 * `fixHeadAcceptable`'s own tests use. Changes NOTHING about WHEN the rung declines: the call
 * site's guard is untouched and this runs only after that guard has already fired.
 */
export type UncreditableHeadReason = "head_unresolved" | "foreign_run_branch" | "not_a_run_branch" | "unclassified";

export function uncreditableHeadReason(
  head: string | undefined,
  taskId: string,
  synthetic: boolean,
): UncreditableHeadReason {
  if (!head) return "head_unresolved";
  if (fixHeadAcceptable(head, taskId, synthetic)) return "unclassified";
  return isDispatchedRunBranch(head) ? "foreign_run_branch" : "not_a_run_branch";
}

const TERMINAL_UNCREDITABLE_HEAD_STEP = "sweep.fix.uncreditable_head";
/** W1-T3168: a foreign-head decline that did NOT escalate because the PR is not stuck. Ledgered so
 *  the suppression is legible — "we saw this and chose not to page you" must be greppable. */
const TERMINAL_UNCREDITABLE_HEAD_HEALTHY_STEP = "sweep.terminal_head.not_stuck";
const TERMINAL_UNCREDITABLE_HEAD_ESCALATED_STEP = "sweep.fix.uncreditable_head_escalated";
const TERMINAL_UNCREDITABLE_HEAD_PATTERN =
  '"step":"sweep\\.fix\\.uncreditable_head"|"step":"sweep\\.fix\\.uncreditable_head_escalated"';

/**
 * W1-T3168 — is a foreign-head PR actually STUCK, or merely not fleet-owned?
 *
 * The fix rung refuses a branch it does not own (W1-T296) and that refusal is correct. What did
 * NOT follow is that a human must be interrupted: "the rung declines to act on this PR" and "a
 * person must decide something about this PR" are different statements, and the producer collapsed
 * them. MEASURED 2026-09-08: issues #4623 and #4624 asked the operator to discard PRs #4619 and
 * #4621 minutes after they opened, both healthy; #4621 then merged on its own.
 *
 * STUCK is read off the rollup {@link OpenPrView} already carries — no extra GitHub read: required
 * checks RED, or a review that has come back FAILURE. Anything else that is positively healthy
 * (checks green or still running, review not failing) is a PR whose author is presumably still
 * working, which is the ordinary case for every operator-authored and every human contribution.
 *
 * INDETERMINATE ESCALATES. `"none"` on both is not evidence of health — it is the absence of
 * evidence, and it takes the same fail-open direction `EscalationReconcileCandidate.indeterminate`
 * already takes ("treat as neither resolved nor live").
 */
export function foreignHeadIsStuck(pr: Pick<OpenPrView, "reviewState" | "checksState">): boolean {
  if (pr.checksState === "red") return true;
  if (pr.reviewState === "failure") return true;
  // Positively healthy: checks are green or still running AND the review has not failed.
  if (pr.checksState === "green" || pr.checksState === "pending") return false;
  return true; // checksState "none" — unreadable, not healthy
}

interface TerminalUncreditableHead {
  prNumber: number;
  headSha: string;
  head: string;
  taskId: string;
  cause: "review" | "ci" | "conflict";
  escalated: boolean;
}

/**
 * W1-T2723 — process-lifetime index of terminal, head-SHA-keyed fix-rung declines. The first
 * lookup after a daemon boot reconstructs it from archive∪live ledger history; later sweep-effect
 * instances reuse the compact map and update it synchronously when they emit a new terminal row.
 * Rotation is therefore harmless without decompressing the full corpus on every poll.
 */
const terminalUncreditableHeadsByLedger = new Map<string, Map<string, TerminalUncreditableHead>>();

function terminalUncreditableHeadKey(prNumber: number, headSha: string): string {
  return `${prNumber}:${headSha}`;
}

function terminalUncreditableHeads(ledgerPath: string): Map<string, TerminalUncreditableHead> {
  const cached = terminalUncreditableHeadsByLedger.get(ledgerPath);
  if (cached) return cached;

  const union = resolveLedgerUnion(dirname(ledgerPath), TERMINAL_UNCREDITABLE_HEAD_PATTERN);
  // A fresh fixture/installation has no rotations. In that one case, use the live ledger; once
  // rotations exist, only a complete archive∪live union is accepted so a rotated terminal marker
  // can never silently disappear and re-enable the GraphQL loop.
  const rows = union.ok
    ? parseLedger(union.matches.join("\n"))
    : union.archiveCount === 0
      ? readLedgerLines(ledgerPath)
      : [];
  const terminals = new Map<string, TerminalUncreditableHead>();
  for (const row of rows) {
    if (
      row.step !== TERMINAL_UNCREDITABLE_HEAD_STEP ||
      row.reason !== "not_a_run_branch" ||
      row.terminal !== true ||
      typeof row.pr_number !== "number" ||
      typeof row.head_sha !== "string" ||
      typeof row.head !== "string" ||
      typeof row.repair_task_id !== "string" ||
      (row.cause !== "review" && row.cause !== "ci" && row.cause !== "conflict")
    ) {
      continue;
    }
    terminals.set(terminalUncreditableHeadKey(row.pr_number, row.head_sha), {
      prNumber: row.pr_number,
      headSha: row.head_sha,
      head: row.head,
      taskId: row.repair_task_id,
      cause: row.cause,
      escalated: false,
    });
  }
  for (const row of rows) {
    if (
      row.step !== TERMINAL_UNCREDITABLE_HEAD_ESCALATED_STEP ||
      typeof row.pr_number !== "number" ||
      typeof row.head_sha !== "string"
    ) {
      continue;
    }
    const terminal = terminals.get(terminalUncreditableHeadKey(row.pr_number, row.head_sha));
    if (terminal) terminal.escalated = true;
  }
  terminalUncreditableHeadsByLedger.set(ledgerPath, terminals);
  return terminals;
}

/**
 * W1-T2402: does `e` — whatever `dispatchFix`'s catch just caught — carry a SIGNAL TERMINATION,
 * and if so what is known about what the killed spawn spent? Read STRUCTURALLY off the error
 * object's own `signal`/`costUsd` properties, never by string-matching the free-text `.message`
 * a caller would otherwise have to grep for "terminated by signal SIGKILL" — the SDK's own
 * wording (`@anthropic-ai/claude-agent-sdk`'s `sdk.mjs`: `getProcessExitError` builds
 * `Error("Claude Code process terminated by signal " + signal + …)` and its own `_n` helper
 * `Object.assign`s `{signal, errorClass: "process_killed_by_signal", telemetryMessage}` directly
 * onto that `Error` before rejecting with it). That literal string appears nowhere in this
 * repo's own source, so reading it by substring would be exactly the class of misread this repo
 * has already been burned by twice (`fallback_push` matching a prose mention, `credential_expired`
 * matching 191 unrelated `containment.probe` rows) — LEARNINGS. The SDK's own error propagates
 * unwrapped up through `collectWorkerResult`'s `if (!sawResult) throw err` and `spawnWorker`'s own
 * pass-through catch (worker.ts) whenever ITS OWN clock-bound watchdog did not itself trip, so the
 * `signal` property really does survive, unaltered, all the way to this catch.
 */

/**
 * THE SIGNAL ALONE NEVER DECIDES ANYTHING (the shard's own correction to its brief): this fleet
 * sends itself the identical `SIGKILL` from at least three of its OWN paths (`killProcessGroup`'s
 * default, `deployer.ts`'s forced-deploy kickstart, W1-T1044's wall-clock reclaim) — so this
 * function only ever RECORDS the signal, structurally; it does not classify who sent it, and (see
 * {@link dispatchFixCatchOutcome}) it never changes whether the strike this call already spent
 * gets swallowed or propagated.
 *
 * `undefined` for an ordinary in-process failure (a failed `git`, a missing binary, a bad `gh`
 * response) that carries no such field — the existing, unchanged `sweep.fix.error` shape.
 */
export function fixDispatchSignalDeath(e: unknown): { signal: string; costUsd: number } | undefined {
  if (typeof e !== "object" || e === null) return undefined;
  const signal = (e as { signal?: unknown }).signal;
  if (typeof signal !== "string" || signal.length === 0) return undefined;
  const costUsd = (e as { costUsd?: unknown }).costUsd;
  // W1-T2402 Q2(a): `0` — never guessed higher — is the honest floor when the kill lands before
  // any SDK result envelope ever arrives, which is what every real signal kill on this fleet's
  // own spawn path does: `collectWorkerResult` only ever populates a cost figure off a
  // `type:"result"` envelope, and a pre-envelope throw means that envelope never arrived, so
  // there is nothing truthful to report beyond zero. Reads an explicit numeric `.costUsd` off
  // `e` when one IS present — forward-compatible with a future caller that does carry one — so
  // this never regresses once that becomes available; never guessed otherwise.
  return { signal, costUsd: typeof costUsd === "number" ? costUsd : 0 };
}

/**
 * W1-T2444 — THE THREE PREDICATES, READ OFF `dispatchFix`'s OWN CATCH, NOT RE-DERIVED FROM A
 * LEDGER SWEEP. `sweep.fix.error` today is 135 historical rows that split 55/42/38 across a
 * shared worker home (W1-T2441), a shared `.git/config` lock (`checkout -B` contention across
 * concurrent sweep worktrees), and GitHub GraphQL rate-limit exhaustion — three unrelated
 * defects with DISJOINT windows, so no rate anyone quotes off the bare step name describes a
 * single real process. This function is the classifier, so a future rate can name its class
 * instead of averaging over silence.
 *
 * ORDER MATTERS, first match wins, same order the ledger sweep used to derive the 55/42/38 split:
 *   1. a signal death — read STRUCTURALLY off `signalDeath`, never by matching "SIGKILL" in the
 *      free-text message (the same trap {@link fixDispatchSignalDeath}'s own doc closes) — is
 *      `"sigkill"`.
 *   2. `Command failed: git … checkout -B …` (the linked-worktree writing upstream-tracking
 *      config into the CANONICAL clone's `.git/config`, and losing the lock race) is
 *      `"checkout_b"`.
 *   3. `Command failed: gh pr view …` (37 of 38 in the historical corpus were the primary
 *      GraphQL budget; the 38th an unrelated `HTTP 503` this same predicate happens to cover) is
 *      `"gh_pr_view"`.
 * Anything else is left OUT of `ledgerFields` entirely — never forced into a class, never
 * written as the string `"unclassified"` — because a fourth cause existing tomorrow must not
 * silently misreport as one of today's three.
 */
export function fixDispatchErrorClass(
  message: string,
  signalDeath: { signal: string; costUsd: number } | undefined,
): string | undefined {
  if (signalDeath) return "sigkill";
  if (/Command failed: git\b.*\bcheckout -B\b/.test(message)) return "checkout_b";
  if (/Command failed: gh pr view\b/.test(message)) return "gh_pr_view";
  return undefined;
}

/**
 * W1-T2402: the WHOLE of `dispatchFix`'s catch decision, pulled out pure so every branch is
 * unit-testable without spawning anything. `ledgerFields` is what `sweep.fix.error` gets spread
 * with — the existing `error` string PLUS `signal`/`cost_usd` when {@link fixDispatchSignalDeath}
 * finds them, PLUS (W1-T2444) `class` when {@link fixDispatchErrorClass} recognises the failure —
 * the SAME conditional-spread shape `signal`/`cost_usd` already established, not a new
 * convention. `rethrow` mirrors W1-T1127's OWN `dispatchStarted` rule byte-for-byte and
 * UNCHANGED by this task: a strike already spent (`dispatchStarted`) keeps this swallowed here so
 * `runSweep` keeps recording `acted:true`, exactly as it does today; a failure before any strike
 * still propagates to `runSweep`'s own `catch`, which already records `acted:false`. Nothing here
 * paces, throttles, sleeps, or awaits — it is synchronous, and reads no clock. No new ledger step
 * is introduced — this is still written under `sweep.fix.error`, unchanged, so
 * `DECISION_RELEVANT_LEDGER_STEPS` (lib/ledger.ts) needs no update.
 */
export function dispatchFixCatchOutcome(e: unknown, dispatchStarted: boolean): { ledgerFields: Record<string, unknown>; rethrow: boolean } {
  const signalDeath = fixDispatchSignalDeath(e);
  const message = String((e as Error)?.message ?? e);
  const errorClass = fixDispatchErrorClass(message, signalDeath);
  return {
    ledgerFields: {
      error: message,
      ...(signalDeath ? { signal: signalDeath.signal, cost_usd: signalDeath.costUsd } : {}),
      ...(errorClass ? { class: errorClass } : {}),
    },
    rethrow: !dispatchStarted,
  };
}


type SweepRuntimeFn = (...args: any[]) => any;
type SweepRuntimeCtor = new (...args: any[]) => any;
type RegisteredFixOwnerSnapshot = any;
type RollupCheck = RollupCheckEntry;

function requiredSweepRuntime<T extends SweepRuntimeFn>(name: string): T {
  return ((..._args: Parameters<T>) => {
    throw new Error(`buildSweepEffects requires ${name} from its entrypoint adapter`);
  }) as unknown as T;
}

export function requiredSweepRuntimeCtor<T extends SweepRuntimeCtor>(name: string): T {
  return (class {
    constructor() {
      throw new Error(`buildSweepEffects requires ${name} from its entrypoint adapter`);
    }
  }) as unknown as T;
}

function prNumberFromRef(ref: string): number | undefined {
  const urlMatch = ref.match(/\/pull\/(\d+)/);
  if (urlMatch) return Number(urlMatch[1]);
  const bareMatch = ref.match(/#?(\d+)/);
  return bareMatch ? Number(bareMatch[1]) : undefined;
}

async function armAndLogOutcome(
  prUrl: string,
  taskId: string | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
  arm: (prUrl: string, taskId: string | undefined) => ArmOutcome | ArmAttemptResult | Promise<ArmOutcome | ArmAttemptResult> = armAutoMergeDetailedAsync,
  lane: ArmLane = "operator",
  headSha?: string,
): Promise<ArmOutcome> {
  // W1-T5781: awaited, so the production arm's plan merge-safety reads run off the daemon loop.
  const result = await arm(prUrl, taskId);
  const outcome = typeof result === "string" ? result : result.outcome;
  const error = typeof result === "string" ? undefined : result.error;
  const rateLimit = typeof result === "string" ? undefined : result.rateLimit;
  const directMergePreflight = typeof result === "string" ? undefined : result.directMergePreflight;
  logArmAttribution(
    log,
    outcome,
    prUrl,
    taskId,
    lane,
    { ...(error !== undefined ? { outcome, error } : { outcome }), ...(headSha !== undefined ? { head_sha: headSha } : {}) },
    rateLimit,
    directMergePreflight,
    typeof result === "string" ? undefined : result.ratchetJudge,
  );
  return outcome;
}

export function sweepArmAttemptOutcome(
  outcome: ArmOutcomeName,
  attemptError: string | undefined,
): ArmOutcomeName | ArmAttemptOutcome {
  if (outcome !== "arm-error-ignored" || attemptError === undefined) return outcome;
  const failureClass = armFailureAction(attemptError);
  if (failureClass === "direct-merge") return outcome;
  return { outcome, failureClass };
}

export interface RegisteredFixOwnerRecoveryDeps {
  capture: SweepRuntimeFn;
  remove: SweepRuntimeFn;
  publishAhead?: SweepRuntimeFn;
  preserveDiverged?: SweepRuntimeFn;
  preserveTrackedDirty?: SweepRuntimeFn;
  /** W1-T5974: preserves a staged-only residue the PR's head has moved past; returns its recovery ref. */
  preserveStagedResidue?: SweepRuntimeFn;
  resetTrackedDirty?: SweepRuntimeFn;
  /** W1-T6355: preserves, then clears, an ended run's untracked-only owner; returns its recovery ref. */
  preserveUntracked?: SweepRuntimeFn;
  preserveStaleDirty?: SweepRuntimeFn;
  clearStaleDirty?: SweepRuntimeFn;
}

export interface FixOwnerResidue {
  markerKind: "MERGE_HEAD" | "CHERRY_PICK_HEAD" | "REVERT_HEAD" | null;
  markerSha: string | null;
  unmergedPaths: string[];
  unmergedMore: number;
  stagedPaths: string[];
  stagedMore: number;
  status: string;
  /** W1-T5918's name for a staged-only residue with no operation marker. Since W1-T6362 the sweep
   *  no longer refuses it for a dead owner: it is preserved from the index, then reset and reclaimed. */
  refusal?: "owner_dirty_staged_only_refused";
}

// ── W1-T3691 — STALE-REVIEWER-CODE SKIP RECURRENCE. A `review.skipped_stale_reviewer_code` skip
// (`buildReviewerCodeFreshnessGate`, src/run-task.ts) is re-derived every sweep and, on its own, is
// silent and terminal: this tracks whether the SAME code sha keeps recurring across sweeps and
// turns that into a tiered response -- silent, held-and-visible, restart, or (if a restart already
// happened and the sha still has not moved) needs-human. A COUNTER, NOT A TIMER: sweep cadence
// varies with load, so a wall-clock floor tuned on an idle fleet would be wrong on a busy one --
// see this task's own plan record for the incident this closes. FALSIFIER:
// test/a-repeated-stale-reviewer-skip-asks-for-a-restart.test.ts ─────────────────────────────

/** How many consecutive sweep passes must observe the SAME stale code sha before the daemon asks
 *  for its own freshness restart (the SAME exit `daemon.stale_code` already uses, daemon.ts's
 *  `stopForFreshness`). A single skip is ordinary -- the daemon may already be seconds from a
 *  restart it planned for an unrelated reason -- and must change nothing, so this floor is never 1. */
export const STALE_REVIEWER_SKIP_RESTART_STREAK = 3;

/** One sweep pass's own stale-reviewer-code reading, as `buildReviewerCodeFreshnessGate`'s
 *  `staleThisPass()` (src/run-task.ts) reports it via `SweepCycleOutcome.reviewerCodeStale`
 *  (daemon.ts). `prNumbers` is the pull requests this pass skipped review for at `codeSha` --
 *  omitted where a caller does not yet carry that attribution, in which case a rendered blocker
 *  names none rather than guessing. */
export interface StaleReviewerSkipObservation {
  codeSha: string;
  originMainSha: string;
  prNumbers?: readonly number[];
}

/** Carried by the daemon's own tick loop across sweep passes (never rebuilt per call), and
 *  reconstructed at boot from the ledger's own history (`priorStaleReviewerRecurrenceState`,
 *  daemon.ts) so a real process restart cannot forget it already asked once -- design (v)'s
 *  falsifier: "restart again on an unchanged sha and the fourth test fails." */
export interface StaleReviewerRecurrenceState {
  /** The code sha the most recent observation was at. */
  codeSha: string;
  /** Consecutive sweep passes this sha has now been observed at, including the first sighting. */
  streak: number;
  /** True once a freshness restart has ACTUALLY been requested for this exact sha. Set by the
   *  CALLER at the point it really acts on a `"restart"` action (daemon.ts), never by
   *  `trackStaleReviewerSkipRecurrence` itself: a `"restart"` action the caller declines to act on
   *  this tick (dispatch is mid-admission, see daemon.ts's `daemon.freshness_deferred`) must be
   *  asked for again next tick, not silently believed already granted. */
  restartRequested: boolean;
}

export type StaleReviewerRecurrenceAction =
  | { kind: "silent" }
  | { kind: "held"; codeSha: string; originMainSha: string; streak: number }
  | { kind: "restart"; codeSha: string; originMainSha: string; streak: number }
  | { kind: "needs_human"; codeSha: string; originMainSha: string; reason: string };

export interface StaleReviewerRecurrenceResult {
  /** The state to carry into the NEXT observation. `undefined` only when this pass had no stale
   *  reading at all -- the daemon moved (or nothing needed review), so there is nothing left to
   *  track. */
  state: StaleReviewerRecurrenceState | undefined;
  action: StaleReviewerRecurrenceAction;
}

/**
 * W1-T3691 (design i, ii, iv, v) — the pure decision at the heart of the fix.
 *
 *  - No observation this pass ⇒ silent, state reset (iv: the daemon moved).
 *  - A NEW sha ⇒ silent, streak resets to 1 (iii: a daemon that did move is not stuck).
 *  - The SAME sha recurring, below the restart streak ⇒ "held" -- visible before it is acted on
 *    (iii), but nothing else changes (iv: only the FIRST sighting of a sha is a single skip, but a
 *    second one is still below the acted-on floor here).
 *  - The SAME sha at or past the restart streak, no restart requested yet ⇒ "restart" (ii).
 *  - The SAME sha with a restart already requested ⇒ "needs_human" (v) -- the pin looks
 *    deliberate, so this never asks for another restart.
 */
export function trackStaleReviewerSkipRecurrence(
  observation: StaleReviewerSkipObservation | undefined,
  prior: StaleReviewerRecurrenceState | undefined,
  restartStreak: number = STALE_REVIEWER_SKIP_RESTART_STREAK,
): StaleReviewerRecurrenceResult {
  if (!observation) {
    return { state: undefined, action: { kind: "silent" } };
  }
  const sameSha = prior !== undefined && prior.codeSha === observation.codeSha;
  if (!sameSha) {
    return {
      state: { codeSha: observation.codeSha, streak: 1, restartRequested: false },
      action: { kind: "silent" },
    };
  }
  const streak = prior!.streak + 1;
  const state: StaleReviewerRecurrenceState = {
    codeSha: observation.codeSha,
    streak,
    restartRequested: prior!.restartRequested,
  };
  if (prior!.restartRequested) {
    return {
      state,
      action: {
        kind: "needs_human",
        codeSha: observation.codeSha,
        originMainSha: observation.originMainSha,
        reason:
          `daemon requested a freshness restart over stale reviewer code at ${observation.codeSha.slice(0, 7)} ` +
          `and came back on the SAME sha -- looks pinned behind origin/main ` +
          `(${observation.originMainSha.slice(0, 7)}) rather than transiently behind it, not retrying`,
      },
    };
  }
  if (streak < restartStreak) {
    return {
      state,
      action: { kind: "held", codeSha: observation.codeSha, originMainSha: observation.originMainSha, streak },
    };
  }
  return {
    state,
    action: { kind: "restart", codeSha: observation.codeSha, originMainSha: observation.originMainSha, streak },
  };
}

/** (design iii) — the BLOCKERS BY CLASS row a held review queue renders as once the daemon has
 *  recorded the recurrence. Wiring this into the status board's own `BlockerRow` union
 *  (status-board.ts) is out of this task's declared file scope (`src/lib/sweep.ts`,
 *  `src/lib/daemon.ts` only) -- see this PR's Follow-ups. `renderHeldReviewQueueBlocker` is the
 *  text an operator reads today, off the `review.stale_reviewer_held` /
 *  `review.stale_reviewer_restart_requested` ledger lines the daemon writes for a
 *  `"held"`/`"restart"` action. */
export interface HeldReviewQueueBlocker {
  kind: "held_review_queue";
  codeSha: string;
  originMainSha: string;
  prNumbers: readonly number[];
  streak: number;
}

export function renderHeldReviewQueueBlocker(blocker: HeldReviewQueueBlocker): string {
  const prList =
    blocker.prNumbers.length > 0 ? blocker.prNumbers.map((n) => `#${n}`).join(", ") : "no pull requests attributed yet";
  return (
    `held review queue: code ${blocker.codeSha.slice(0, 7)} has lagged origin/main ` +
    `${blocker.originMainSha.slice(0, 7)} for ${blocker.streak} consecutive sweep${blocker.streak === 1 ? "" : "s"} ` +
    `-- holding ${prList}`
  );
}

export type PlanScopedFixRoundInput = {
  pr: OpenPrView;
  task: { id: string; title: string; files: readonly string[] };
  worktreePath: string;
  title: string;
  body: string;
  runId?: string;
  lastRefusal?: string;
  /** W1-T9289: the PR is dirty — merge origin/main into the head and resolve the plan text on the merged tree. */
  conflict?: boolean;
  admission?: AdmissionSettings;
  deps: Pick<BuildSweepEffectsDeps, "log"> & Pick<BodyRepairDeps, "execProof"> & {
    runGit?: (args: string[]) => string;
    preflight?: BuildSweepEffectsDeps["planPrPreflightImpl"];
    feedbackRead?: AdmissionRead;
    spawn: (prompt: string) => Promise<string>;
    push: (sha: string) => unknown;
    updateMetadata: (metadata: { title: string; body: string }) => Promise<void>;
  };
};

